def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    # dp[i][j] represents A(i, j)
    dp = [[0] * (n) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            dp[i][j] = (i - j) * dp[i-1][j-1] + (j + 1) * dp[i-1][j]

    return dp[n][m]

def eulerian_num(n, m):
    if m < 0 or m > n:
        return 0
    if m == 0 or n == 0:
        return 1
    # Use a 1D DP array for efficiency
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(min(i, m), -1, -1):
            dp[j] = (j + 1) * dp[j] + (i - j) * dp[j - 1]
    return dp[m]

